from decimal import Decimal

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.pricing import format_price, parse_price

# Every price from 0.00 to 9,999,999.99 in whole cents: drawn as a count of cents, in either
# of the two ways the same price can be written as a Decimal (`12.50` and `12.5`).
_CENTS = st.integers(min_value=0, max_value=999_999_999).map(lambda c: Decimal(c).scaleb(-2))
PRICES = st.one_of(_CENTS, _CENTS.map(lambda price: price.normalize()))


def test_format_pads_to_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"
    assert format_price(Decimal("0")) == "0.00"


def test_format_groups_thousands_by_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"
    assert format_price(Decimal("1234567.89")) == "1,234,567.89"


def test_format_does_not_group_below_a_thousand() -> None:
    assert format_price(Decimal("999.99")) == "999.99"


def test_format_takes_both_ends_of_the_range() -> None:
    assert format_price(Decimal("0.00")) == "0.00"
    assert format_price(Decimal("9999999.99")) == "9,999,999.99"


@pytest.mark.parametrize("price", ["10000000.00", "-0.01"])
def test_format_rejects_a_price_outside_the_range(price: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal(price))


@pytest.mark.parametrize("price", ["0.005", "12.345", "1234.5678"])
def test_format_rejects_a_fraction_of_a_cent_instead_of_rounding(price: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal(price))


def test_parse_reads_a_printed_price() -> None:
    assert parse_price("1,234.50") == Decimal("1234.50")
    assert parse_price("12.50") == Decimal("12.50")
    assert parse_price("1,234,567.89") == Decimal("1234567.89")


def test_parse_reads_a_price_with_the_commas_left_out() -> None:
    assert parse_price("1234.50") == Decimal("1234.50")
    assert parse_price("1234567.89") == Decimal("1234567.89")


def test_parse_takes_both_ends_of_the_range() -> None:
    assert parse_price("0.00") == Decimal("0.00")
    assert parse_price("9,999,999.99") == Decimal("9999999.99")


# Hardest seam 1: compared as text, so a result equal in value that prints as `1234.5` fails.
@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("1,234.50", "1234.50"),
        ("1234.50", "1234.50"),
        ("1,000.00", "1000.00"),
        ("0.00", "0.00"),
        ("9,999,999.99", "9999999.99"),
    ],
)
def test_parse_result_is_in_cents(text: str, expected: str) -> None:
    assert str(parse_price(text)) == expected


@pytest.mark.parametrize("text", ["12.5", "12", "12.", "12.500"])
def test_parse_rejects_anything_but_two_decimals(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["1,23.00", "12,34.50", ",123.00", "1,234,56.00"])
def test_parse_rejects_misplaced_commas(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["", "abc"])
def test_parse_rejects_text_that_is_no_number(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["$12.50", "12.50 EUR", "-12.50", "12,50", "1.234,50", "1 234.50"])
def test_parse_rejects_signs_and_other_separators(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["10,000,000.00", "10000000.00"])
def test_parse_rejects_a_text_above_the_range(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@given(price=PRICES)
def test_I1_a_printed_price_reads_back_as_the_same_price(price: Decimal) -> None:
    assert parse_price(format_price(price)) == price

