from collections.abc import Callable

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.inventory import Shelf, hold, release

FULL = Shelf(sku="W-1", on_hand=5, held=0)
PARTLY_HELD = Shelf(sku="W-1", on_hand=2, held=3)


def test_hold_moves_units_from_on_hand_to_held() -> None:
    assert hold(FULL, 3) == Shelf(sku="W-1", on_hand=2, held=3)


def test_release_moves_units_from_held_back_to_on_hand() -> None:
    assert release(PARTLY_HELD, 2) == Shelf(sku="W-1", on_hand=4, held=1)


def test_hold_returns_a_new_shelf_and_leaves_the_argument_untouched() -> None:
    shelf = Shelf(sku="W-1", on_hand=5, held=0)
    after = hold(shelf, 3)
    assert after is not shelf
    assert shelf == Shelf(sku="W-1", on_hand=5, held=0)


def test_release_returns_a_new_shelf_and_leaves_the_argument_untouched() -> None:
    shelf = Shelf(sku="W-1", on_hand=2, held=3)
    after = release(shelf, 2)
    assert after is not shelf
    assert shelf == Shelf(sku="W-1", on_hand=2, held=3)


def test_hold_of_everything_on_hand_is_allowed() -> None:
    assert hold(FULL, 5) == Shelf(sku="W-1", on_hand=0, held=5)


def test_release_of_everything_held_is_allowed() -> None:
    assert release(PARTLY_HELD, 3) == Shelf(sku="W-1", on_hand=5, held=0)


@pytest.mark.parametrize("quantity", [0, -1])
def test_hold_of_a_non_positive_quantity_is_refused(quantity: int) -> None:
    with pytest.raises(ValueError, match="quantity must be positive"):
        hold(FULL, quantity)


@pytest.mark.parametrize("quantity", [0, -1])
def test_release_of_a_non_positive_quantity_is_refused(quantity: int) -> None:
    with pytest.raises(ValueError, match="quantity must be positive"):
        release(PARTLY_HELD, quantity)


def test_cannot_hold_more_than_on_hand() -> None:
    with pytest.raises(ValueError, match="on hand"):
        hold(FULL, 6)


def test_cannot_release_more_than_held() -> None:
    with pytest.raises(ValueError, match="held"):
        release(PARTLY_HELD, 4)


@pytest.mark.parametrize("quantity", [0, -1, 6])
def test_refused_hold_changes_nothing(quantity: int) -> None:
    shelf = Shelf(sku="W-1", on_hand=5, held=0)
    with pytest.raises(ValueError):
        hold(shelf, quantity)
    assert shelf == Shelf(sku="W-1", on_hand=5, held=0)


@pytest.mark.parametrize("quantity", [0, -1, 4])
def test_refused_release_changes_nothing(quantity: int) -> None:
    shelf = Shelf(sku="W-1", on_hand=2, held=3)
    with pytest.raises(ValueError):
        release(shelf, quantity)
    assert shelf == Shelf(sku="W-1", on_hand=2, held=3)


# Hardest seam 1: units are moved, not made.
def test_units_are_moved_not_made_by_a_hold_and_a_release() -> None:
    after_hold = hold(FULL, 3)
    assert after_hold.on_hand + after_hold.held == 5
    after_release = release(after_hold, 2)
    assert after_release.on_hand + after_release.held == 5


CALLS = st.lists(st.tuples(st.sampled_from([hold, release]), st.integers()))


@given(
    start=st.builds(
        Shelf,
        sku=st.text(),
        on_hand=st.integers(min_value=0),
        held=st.integers(min_value=0),
    ),
    calls=CALLS,
)
def test_I1_nothing_on_the_shelf_is_ever_negative(
    start: Shelf, calls: list[tuple[Callable[[Shelf, int], Shelf], int]]
) -> None:
    shelf = start
    for call, quantity in calls:
        try:
            shelf = call(shelf, quantity)
        except ValueError:
            pass
        assert shelf.on_hand >= 0
        assert shelf.held >= 0
